# =================================================================
# MAPA BASE DE GEOMETRÍAS
# ARCHIVO GENERADO AUTOMÁTICAMENTE A PARTIR DE LA DEFINICIÓN: layers.03_rezago_educativo.03_rezago_municipios_indigenas 
# DESCRIPCIÓN: Rezago educativo en municipios índigenas Censo 2020 
# =================================================================

LAYER
  NAME "c_rezago_educativo_analfabeta"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, analfabeta FROM rezago_educativo_censo_2020.rez_mun_indigena WHERE the_geom && !BOX!) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Porcentaje de analfabetismo en municipios índigenas"
    "wms_enable_request" "*"
  END
  CLASS
    NAME "bajo"
    EXPRESSION ([analfabeta] <=14.67)
    STYLE
      OUTLINECOLOR 0 128 0
      WIDTH 0.8
      OPACITY 60
      COLOR 0 128 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "medio"
    EXPRESSION ([analfabeta] >14.67 and [analfabeta] <=22.95)
    STYLE
      OUTLINECOLOR 255 255 0
      WIDTH 0.8
      OPACITY 60
      COLOR 255 255 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "alto"
    EXPRESSION ([analfabeta] >22.95 and [analfabeta] <=28.35)
    STYLE
      OUTLINECOLOR 240 120 15
      WIDTH 0.8
      OPACITY 60
      COLOR 240 120 15
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "muy_alto"
    EXPRESSION ([analfabeta] >28.35)
    STYLE
      OUTLINECOLOR 255 0 0
      WIDTH 0.8
      OPACITY 60
      COLOR 255 0 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
END

